(function () {
  // --------- SCOPE: só /estudiantes ---------
  var onEstudiantesPage = /\/estudiantes\/?$/i.test(location.pathname);
  if (!onEstudiantesPage) return;

  // --------- helpers comuns ---------
  function norm(s){
    return (s || '').toString().normalize('NFD')
      .replace(/[\u0300-\u036f]/g,'').trim();
  }
  function groupOf(el){ return el.closest('.elementor-field-group')||el.parentElement; }
  function removeError(el){
    var g=groupOf(el); if(!g) return;
    g.classList.remove('evc-has-error');
    var old=g.querySelector('.evc-error'); if(old) old.remove();
  }
  function removeErrorsIn(container){
    if(!container) return;
    container.querySelectorAll('.evc-error').forEach(function(n){ n.remove(); });
    container.querySelectorAll('.evc-has-error').forEach(function(g){ g.classList.remove('evc-has-error'); });
  }
  function after(ref,node){ ref.parentNode.insertBefore(node,ref.nextSibling); }
  function showError(el,msg){
    var g=groupOf(el); if(!g) return;
    removeError(el);
    var err=document.createElement('div');
    err.className='evc-error';
    err.textContent=msg;
    var wrap=g.querySelector('.elementor-select-wrapper');
    var subgroup=g.querySelector('.elementor-field-subgroup');
    if(wrap && (wrap.contains(el) || el.tagName==='SELECT')) after(wrap,err);
    else if(subgroup && subgroup.contains(el)) after(subgroup,err);
    else after(el,err);
    g.classList.add('evc-has-error');
  }

  // --------- localizar o formulário alvo ---------
  function findForm() {
    var byId = document.getElementById('estudiantes');
    if (byId && byId.classList.contains('elementor-form')) return byId;
    var candidates = Array.from(document.querySelectorAll('form.elementor-form'));
    return candidates.find(function (f) {
      return (
        f.querySelector('input[name="form_id"][value="5fe71de"]') ||
        f.querySelector('input[name="post_id"][value="22721"]') ||
        f.querySelector('input[name="queried_id"][value="22721"]')
      );
    }) || null;
  }

  // --------- mapeamento (residência -> grupo de projetos) ---------
  function resolveResidenciaGroup(wrapper, countryRaw){
    var v = norm(countryRaw).toLowerCase();
    if (!v || v === 'selecciona') return null;

    var G = {
      chile:    wrapper.querySelector('.elementor-field-group-proyectos_chile'),
      uruguay:  wrapper.querySelector('.elementor-field-group-proyectos_uruguay'),
      pr:       wrapper.querySelector('.elementor-field-group-proyectos_pr'),
      no:       wrapper.querySelector('.elementor-field-group-proyectos_no')
    };

    if (v === 'chile') return G.chile;
    if (v === 'uruguay') return G.uruguay;
    if (v === 'puerto rico' || v === 'estados unidos') return G.pr;
    if (v === 'costa rica') return G.no;
    if (/^colombia\s*-\s*/.test(v)) return G.no;
    return null;
  }

  // --------- limitar seleção máxima e notas ---------
  function bindMaxSelections(groupEl, max) {
    if (!groupEl) return;

    var subgroup = groupEl.querySelector('.elementor-field-subgroup') || groupEl;
    var checks   = Array.from(groupEl.querySelectorAll('input[type="checkbox"]'));
    if (!checks.length) return;

    var note = groupEl.querySelector('.evc-max-note');
    if (!note) {
      note = document.createElement('div');
      note.className = 'evc-max-note';
    }
    note.textContent = 'Máx. ' + max + ' opciones.';
    note.style.margin = '0 0 6px 0';
    note.style.fontSize = '12px';
    note.style.color = '#fff';

    var firstOption = subgroup.querySelector('.elementor-field-option');
    if (firstOption && note !== firstOption.previousSibling) {
      subgroup.insertBefore(note, firstOption);
    } else if (!firstOption) {
      subgroup.insertBefore(note, subgroup.firstChild);
    }

    function updateState() {
      var checked = checks.filter(function (c){ return c.checked; });
      var atLimit = checked.length >= max;

      checks.forEach(function (c) {
        if (!c.checked) {
          c.disabled = atLimit;
          if (atLimit) c.setAttribute('aria-disabled','true');
          else c.removeAttribute('aria-disabled');
        }
      });

      note.style.color = atLimit ? '#0dd3ad' : '#fff';
    }

    if (groupEl.dataset.maxBound !== '1') {
      checks.forEach(function (c) {
        c.addEventListener('change', function (e) {
          var checkedCount = checks.filter(function (x){ return x.checked; }).length;
          if (checkedCount > max) {
            e.target.checked = false; // impede ultrapassar
          }
          updateState();

          // revalida grupo ao marcar/desmarcar
          var wrapper = groupEl.closest('.elementor-form-fields-wrapper');
          if (wrapper) validateProjectsRequired(wrapper);
        });
      });
      groupEl.dataset.maxBound = '1';
    }

    updateState();
  }

  // --------- mostrar grupos por país ---------
  function initResidencia(wrapper) {
    var selectResidencia = wrapper.querySelector('#form-field-residencia');
    if (!selectResidencia) return;

    var allProyectoGroups = Array.from(
      wrapper.querySelectorAll('[class*="elementor-field-group-proyectos_"]')
    );

    function clearChecks(groupEl){
      if (!groupEl) return;
      groupEl.querySelectorAll('input[type="checkbox"]').forEach(function(c){
        c.checked = false;
        c.disabled = false;
        c.removeAttribute('aria-disabled');
      });
    }

    function hideAll(){
      allProyectoGroups.forEach(function(g){
        if (!g) return;
        g.style.display = 'none';
        clearChecks(g);
        removeErrorsIn(g); // limpa erros quando oculta
      });
    }

    function show(el){
      if (!el) return;
      el.style.display = '';
      var max = 2;
      if (el.classList.contains('elementor-field-group-proyectos_no')) max = 2;
      bindMaxSelections(el, max);
    }

    // estado inicial
    hideAll();
    var initialGroup = resolveResidenciaGroup(wrapper, selectResidencia.value);
    if (initialGroup) show(initialGroup);

    // mudanças
    selectResidencia.addEventListener('change', function(e){
      hideAll();
      var g = resolveResidenciaGroup(wrapper, e.target.value);
      if (g) show(g);

      // valida imediatamente ao trocar país
      validateProjectsRequired(wrapper);
    });

    // também aplica limite em todos que existirem na página
    allProyectoGroups.forEach(function (g) { bindMaxSelections(g, 2); });
  }

  // --------- VALIDAÇÃO INLINE (ES) + sem tooltip nativo ---------
  var MSG_REQUIRED='Por favor, completa este campo.';
  var MSG_INVALID='Introduce una respuesta válida.';

  function validateSelectPlaceholder(el){
    if(el.tagName!=='SELECT') return;
    var val=(el.value||'').trim();
    if(val===''||val==='Selecciona') el.setCustomValidity(MSG_REQUIRED);
    else el.setCustomValidity('');
  }
  function validateFileSize(el){
    if(el.type!=='file') return;
    var maxMb=el.getAttribute('data-maxsize');
    if(!maxMb||!el.files||!el.files[0]){ el.setCustomValidity(''); return; }
    var maxBytes=parseFloat(maxMb)*1024*1024;
    var tooBig=[].slice.call(el.files).some(function(f){return f.size>maxBytes;});
    el.setCustomValidity(tooBig?('El archivo supera el tamaño máximo permitido ('+maxMb+' MB).'):'' );
  }
  function messageFor(el){
    var v=el.validity;
    if(v.valueMissing) return MSG_REQUIRED;
    if(v.typeMismatch||v.patternMismatch||v.badInput||v.stepMismatch||v.rangeOverflow||v.rangeUnderflow) return MSG_INVALID;
    return '';
  }
  function validate(el){
    // limpa e aplica regras custom
    el.setCustomValidity('');
    validateSelectPlaceholder(el);
    validateFileSize(el);

    // checagem sem usar texto nativo do browser
    if(!el.checkValidity()){
      var msg = messageFor(el) || MSG_INVALID;
      el.setCustomValidity(msg);  // força ES
      showError(el, msg);
      return false;
    } else {
      removeError(el);
      return true;
    }
  }

  // --------- PROJETOS OBRIGATÓRIO ---------
  function validateProjectsRequired(wrapper){
    var selectResidencia = wrapper.querySelector('#form-field-residencia');
    if (!selectResidencia) return true;

    var group = resolveResidenciaGroup(wrapper, selectResidencia.value);
    if (!group) {
      // país não selecionado (o próprio select já é required)
      return true;
    }

    // limpa erro anterior no grupo antes de validar
    removeErrorsIn(group);

    var checks = Array.from(group.querySelectorAll('input[type="checkbox"]'))
                      .filter(function(c){ return !c.disabled; });
    if (!checks.length) return true;

    var anyChecked = checks.some(function(c){ return c.checked; });
    if (!anyChecked){
      var target = group.querySelector('.elementor-field-subgroup') || checks[0];
      showError(target, 'Selecciona al menos una opción de proyecto.');
      return false;
    }
    return true;
  }

  function wireValidation(form){
    // desativa UI nativa
    form.setAttribute('novalidate','');
    // remove titles que podem “vazar” textos nativos
    form.querySelectorAll('[title]').forEach(function(el){ el.removeAttribute('title'); });
    // bloqueia tooltip nativo em captura
    form.addEventListener('invalid', function(e){ e.preventDefault(); }, true);

    // neutraliza reportValidity de terceiros (Elementor)
    if (typeof form.reportValidity === 'function') {
      form.reportValidity = (function(){
        return function(){
          var controls=[].slice.call(form.querySelectorAll('input, select, textarea'));
          var ok=true;
          controls.forEach(function(el){
            if(el.disabled) return;
            var grp=groupOf(el);
            if(grp && getComputedStyle(grp).display==='none') return; // ignora campos condicionais ocultos
            if(!validate(el)) ok=false;
          });

          // checagem adicional de grupo de projetos
          var wrapper = form.querySelector('.elementor-form-fields-wrapper');
          if (wrapper) {
            if (!validateProjectsRequired(wrapper)) ok=false;
          }

          return ok;
        };
      })();
    }

    var controls=[].slice.call(form.querySelectorAll('input, select, textarea'));
    var wrapper=form.querySelector('.elementor-form-fields-wrapper');

    controls.forEach(function(el){
      var evt=(el.tagName==='SELECT'||['checkbox','radio','file'].includes(el.type))?'change':'input';
      el.addEventListener(evt,function(){
        validate(el);
        if (wrapper) {
          var inProjects = el.closest('[class*="elementor-field-group-proyectos_"]');
          if (inProjects || el.id==='form-field-residencia') {
            validateProjectsRequired(wrapper);
          }
        }
      });
      el.addEventListener('blur',function(){ validate(el); });
    });

    form.addEventListener('submit', function(e){
      var ok=true;
      var controls=[].slice.call(form.querySelectorAll('input, select, textarea'));
      controls.forEach(function(el){
        if(el.disabled) return;
        var grp=groupOf(el);
        if(grp && getComputedStyle(grp).display==='none') return;
        if(!validate(el)) ok=false;
      });

      if (wrapper && !validateProjectsRequired(wrapper)) ok=false;

      if(!ok){
        e.preventDefault();
        var first=form.querySelector('.evc-has-error .elementor-field, .evc-has-error select, .evc-has-error input, .evc-has-error textarea');
        if(first) first.focus({preventScroll:false});
      }
    });
  }

  // --------- TELEFONE: DDI + máscara + E.164 no submit ---------
  (function(){
    const SELECTOR = '#form-field-telefono, input[name="form_fields[telefono]"]';

    function ready(fn){
      if(document.readyState!=='loading'){ fn(); }
      else { document.addEventListener('DOMContentLoaded', fn); }
    }
    function onlyDigits(s){ return (s||'').replace(/\D/g,''); }

    function maskLocalByDDI(cc, digits){
      if (cc === '55') {
        const d = digits.slice(0,11);
        if (d.length <= 2) return d;
        if (d.length <= 6) return '('+d.slice(0,2)+') '+d.slice(2);
        if (d.length <= 10) return '('+d.slice(0,2)+') '+d.slice(2,6)+'-'+d.slice(6);
        return '('+d.slice(0,2)+') '+d.slice(2,7)+'-'+d.slice(7,11);
      }
      if (cc === '1') {
        const d = digits.slice(0,10);
        if (d.length <= 3) return d;
        if (d.length <= 6) return '('+d.slice(0,3)+') '+d.slice(3);
        return '('+d.slice(0,3)+') '+d.slice(3,6)+'-'+d.slice(6,10);
      }
      const d = digits.slice(0,12);
      if (d.length <= 3) return d;
      if (d.length <= 6) return d.slice(0,3)+' '+d.slice(3);
      if (d.length <= 10) return d.slice(0,3)+' '+d.slice(3,6)+'-'+d.slice(6);
      return d.slice(0,4)+' '+d.slice(4,7)+'-'+d.slice(7,12);
    }

    function enhanceOnce(root){
      var tel = (root||document).querySelector(SELECTOR);
      if(!tel || tel._ctmEnhanced) return;
      tel._ctmEnhanced = true;

      // wrapper (lado a lado)
      var wrapper = document.createElement('div');
      wrapper.style.display = 'flex';
      wrapper.style.gap = '6px';
      wrapper.style.alignItems = 'center';
      wrapper.style.width = '100%';

      // input DDI (esquerda)
      var cc = document.createElement('input');
      cc.type = 'text';
      cc.id = 'country_code';
      cc.name = 'form_fields[country_code]';
      cc.placeholder = '+55';
      cc.inputMode = 'numeric';
      cc.autocomplete = 'tel-country-code';
      cc.maxLength = 4; // + e até 3 dígitos
      cc.pattern = '^\\+?\\d{1,3}$';
      cc.style.width = '72px';
      cc.className = 'elementor-field elementor-size-sm elementor-field-textual';

      // insere antes do campo original
      var parent = tel.parentNode;
      parent.insertBefore(wrapper, tel);
      wrapper.appendChild(cc);
      wrapper.appendChild(tel);

      // higiene no campo local
      ['pattern','title','data-rule-pattern','data-msg-pattern'].forEach(function(a){ tel.removeAttribute(a); });
      tel.type = 'text';
      tel.inputMode = 'tel';
      tel.autocomplete = 'tel';
      tel.placeholder = tel.placeholder || 'Seu número';

      // valida/normaliza DDI
      cc.addEventListener('input', function(){
        var v = (cc.value||'').replace(/[^\d+]/g,'');
        if (v.indexOf('+') > 0) v = v.replace(/\+/g,'');
        if (v && v[0] !== '+') v = '+' + v.replace(/\+/g,'');
        var sign = v.startsWith('+') ? '+' : '';
        v = sign + v.replace(/\D/g,'').slice(0,3);
        cc.value = v;

        // re-máscara número local conforme DDI atual
        var m = cc.value.match(/^\+([1-9]\d{0,2})/);
        const code = (m && m[1]) || '55';
        tel.value = maskLocalByDDI(code, onlyDigits(tel.value));
      });

      // só números no local; máscara com hífen
      tel.addEventListener('beforeinput', function(e){
        if (e.inputType==='insertText' && /\D/.test(e.data)) e.preventDefault();
      });
      function remaskLocal(){
        var m = cc.value.match(/^\+([1-9]\d{0,2})/);
        const code = (m && m[1]) || '55';
        tel.value = maskLocalByDDI(code, onlyDigits(tel.value));
      }
      tel.addEventListener('input', remaskLocal);
      tel.addEventListener('paste', function(e){
        e.preventDefault();
        var t = (e.clipboardData||window.clipboardData).getData('text')||'';
        var digits = onlyDigits(t).replace(/^[1-9]\d{0,2}/,'');
        tel.value = digits;
        remaskLocal();
      });

      function setCCOnce(val){
        if(!cc.value.trim()){
          var code = String(val||'').replace(/[^\d]/g,'').slice(0,3);
          if(code) cc.value = '+' + code;
          var dd = code || '55';
          if (!tel.value) tel.placeholder = (dd==='55') ? '(11) 98765-4321'
                                  : (dd==='1') ? '(415) 555-1234'
                                  : 'Seu número';
          tel.value = maskLocalByDDI(dd, onlyDigits(tel.value));
        }
      }
      try {
        fetch('https://ipwho.is/?fields=calling_code').then(function(r){return r.json();})
          .then(function(d){ if(d && d.calling_code){ setCCOnce(d.calling_code); } })
          .catch(function(){});
      } catch(e){}
      try {
        fetch('https://ipapi.co/json/').then(function(r){return r.json();})
          .then(function(d){ if(d && d.country_calling_code){ setCCOnce(d.country_calling_code); } })
          .catch(function(){});
      } catch(e){}

      // Submit → E.164 no campo original (Elementor)
      var form = tel.closest('form');
      if(form && !form._ctmPhoneHook){
        form.addEventListener('submit', function(){
          var ccDigits  = (cc.value || '').replace(/\D/g,'');
          var telDigits = (tel.value || '').replace(/\D/g,'');
          var finalCC   = ccDigits || '55';
          if (telDigits) tel.value = '+' + finalCC + telDigits; // E.164
        });
        form._ctmPhoneHook = true;
      }
    }

    function enhanceBoot(root){
      enhanceOnce(root || document);
    }

    // chama agora; será re-chamado no boot do formulário mais abaixo
    ready(function(){ enhanceBoot(document); });

    // Elementor (re-render/popup)
    if (window.jQuery && window.elementorFrontend) {
      jQuery(window).on('elementor/frontend/init', function () {
        elementorFrontend.hooks.addAction('frontend/element_ready/form.default', function ($scope) {
          enhanceBoot($scope[0]);
        });
      });
    }
  })();

  // --------- FALLBACK ABSOLUTO: bloqueia submit se inválido (capture) ---------
  if (!window._evcProjectsSubmitHook) {
    document.addEventListener('submit', function(e){
      var form = findForm();
      if (!form) return;
      if (form !== e.target && !form.contains(e.target)) return;

      var wrapper = form.querySelector('.elementor-form-fields-wrapper');
      var ok = true;

      var controls = [].slice.call(form.querySelectorAll('input, select, textarea'));
      controls.forEach(function(el){
        if(el.disabled) return;
        var grp = groupOf(el);
        if(grp && getComputedStyle(grp).display === 'none') return;
        if (!validate(el)) ok = false;
      });

      if (wrapper && !validateProjectsRequired(wrapper)) ok=false;

      if (!ok) {
        e.preventDefault();
        e.stopPropagation();
        var first = form.querySelector('.evc-has-error .elementor-field, .evc-has-error select, .evc-has-error input, .evc-has-error textarea');
        if (first) first.focus({ preventScroll: false });
      }
    }, true);
    window._evcProjectsSubmitHook = 1;
  }

  // --------- boot (idempotente por propriedade JS) ---------
  function boot() {
    var form = findForm();
    if (!form || form._evcInit) return;
    var wrapper = form.querySelector('.elementor-form-fields-wrapper');
    if (!wrapper) return;

    // país + limite + notas
    initResidencia(wrapper);

    // validação inline ES + sem tooltip
    wireValidation(form);

    // telefone (garante aplicação após DOM pronto)
    (function reapplyPhone(){
      var tel = wrapper.querySelector('#form-field-telefono, input[name="form_fields[telefono]"]');
      if (!tel || tel._ctmEnhanced) return;
      var evt = document.createEvent('Event');
      evt.initEvent('DOMContentLoaded', true, true);
      document.dispatchEvent(evt);
    })();

    form._evcInit = true; // marca em memória
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }
  window.addEventListener('load', boot);
})();
